        WHEN GL_ACCOUNT_CLASS_ID = 'SGA_EXPENSE' AND GL_ACCOUNT_TYPE_ID = 'OTHER_INCOME' THEN 'OTHER_EXPENSES'
        WHEN GL_ACCOUNT_CLASS_ID = 'SGA_EXPENSE' AND GL_ACCOUNT_TYPE_ID = 'OTHER_RECEIVABLES' THEN 'OTHER_EXPENSES'
        WHEN GL_ACCOUNT_CLASS_ID = 'SGA_EXPENSE' AND GL_ACCOUNT_TYPE_ID = 'OWNERS_EQUITY' THEN 'OTHER_EXPENSES'
        WHEN GL_ACCOUNT_CLASS_ID = 'SGA_EXPENSE' AND GL_ACCOUNT_TYPE_ID = 'PREPAID_EXPENSES' THEN 'OTHER_EXPENSES'
        WHEN GL_ACCOUNT_CLASS_ID = 'SGA_EXPENSE' AND GL_ACCOUNT_TYPE_ID = 'PRODUCT_ACCOUNT' THEN 'OTHER_EXPENSES'
        WHEN GL_ACCOUNT_CLASS_ID = 'SGA_EXPENSE' AND GL_ACCOUNT_TYPE_ID = 'PROFIT_LOSS_ACCOUNT' THEN 'OTHER_EXPENSES'
        WHEN GL_ACCOUNT_CLASS_ID = 'SGA_EXPENSE' AND GL_ACCOUNT_TYPE_ID = 'PROJECTS_UNDER_DEVELOPMENT' THEN 'OTHER_EXPENSES'
        WHEN GL_ACCOUNT_CLASS_ID = 'SGA_EXPENSE' AND GL_ACCOUNT_TYPE_ID = 'PURCHASE_ACCOUNT' THEN 'OTHER_EXPENSES'
        WHEN GL_ACCOUNT_CLASS_ID = 'SGA_EXPENSE' AND GL_ACCOUNT_TYPE_ID = 'PURCHASE_PRICE_VAR' THEN 'OTHER_EXPENSES'
        WHEN GL_ACCOUNT_CLASS_ID = 'SGA_EXPENSE' AND GL_ACCOUNT_TYPE_ID = 'RAWMAT_INVENTORY' THEN 'OTHER_EXPENSES'
        WHEN GL_ACCOUNT_CLASS_ID = 'SGA_EXPENSE' AND GL_ACCOUNT_TYPE_ID = 'RETAINED_EARNINGS' THEN 'OTHER_EXPENSES'
        WHEN GL_ACCOUNT_CLASS_ID = 'SGA_EXPENSE' AND GL_ACCOUNT_TYPE_ID = 'SALES_ACCOUNT' THEN 'OTHER_EXPENSES'
        WHEN GL_ACCOUNT_CLASS_ID = 'SGA_EXPENSE' AND GL_ACCOUNT_TYPE_ID = 'SALES_RETURNS' THEN 'OTHER_EXPENSES'
        WHEN GL_ACCOUNT_CLASS_ID = 'SGA_EXPENSE' AND GL_ACCOUNT_TYPE_ID = 'SUPPLIER_ACCOUNT' THEN 'OTHER_EXPENSES'
        WHEN GL_ACCOUNT_CLASS_ID = 'SGA_EXPENSE' AND GL_ACCOUNT_TYPE_ID = 'TAX_ACCOUNT' THEN 'OTHER_EXPENSES'
        WHEN GL_ACCOUNT_CLASS_ID = 'SGA_EXPENSE' AND GL_ACCOUNT_TYPE_ID = 'UNDEPOSITED_RECEIPTS' THEN 'OTHER_EXPENSES'
        WHEN GL_ACCOUNT_CLASS_ID = 'SGA_EXPENSE' AND GL_ACCOUNT_TYPE_ID = 'UNINVOICED_SHIP_RCPT' THEN 'OTHER_EXPENSES'
        WHEN GL_ACCOUNT_CLASS_ID = 'SGA_EXPENSE' AND GL_ACCOUNT_TYPE_ID = 'WIP_INVENTORY' THEN 'OTHER_EXPENSES'
        WHEN GL_ACCOUNT_CLASS_ID = 'SGA_EXPENSE' AND GL_ACCOUNT_TYPE_ID = 'WRITEOFF' THEN 'OTHER_EXPENSES'
        WHEN GL_ACCOUNT_CLASS_ID = 'SGA_EXPENSE' AND GL_ACCOUNT_TYPE_ID = '_NA_' THEN 'OTHER_EXPENSES'
        ELSE GL_ACCOUNT_COURSE_LABEL_ID
    END

WHERE GL_ACCOUNT_CLASS_ID IS NOT NULL
  AND GL_ACCOUNT_TYPE_ID   IS NOT NULL;